import { createHmac } from "node:crypto";
import { readFileSync } from "node:fs";
import { expect, type Locator, type Page } from "@playwright/test";

// Texts of the app in Italian (the locale of the browser), from the ARB files generated by
// app/tool/strings.py: the tests follow the texts when they change
const texts = JSON.parse(readFileSync(new URL("../../app/lib/l10n/app_it.arb", import.meta.url), "utf8")) as Record<string, string>;

/** Text of the app with its placeholders ({name}) and a plural ({n, plural, =1{...} other{...}}) */
export function t (key: string, values: Record<string, string | number> = {}): string {
	const text = texts[key];
	if (text === undefined) throw new Error(`No text ${key}`);
	return text
		.replace(/\{(\w+), plural, ((?:[^{}]|\{(?:[^{}]|\{\w+\})*\})*)\}/g, (_, name: string, body: string) => {
			const forms = Object.fromEntries([...body.matchAll(/(=\d+|other)\{((?:[^{}]|\{\w+\})*)\}/g)].map(match => [match[1], match[2]]));
			return forms[`=${values[name]}`] ?? forms.other ?? "";
		})
		.replace(/\{(\w+)\}/g, (_, name: string) => String(values[name] ?? `{${name}}`));
}

/** Code of the authenticator app now (RFC 6238, SHA-1, 6 digits, 30 s) from a base32 secret */
export function totp (secret: string, at = Date.now()): string {
	const alphabet = "ABCDEFGHIJKLMNOPQRSTUVWXYZ234567";
	let bits = "";
	for (const char of secret.replace(/[\s=]/g, "").toUpperCase()) bits += alphabet.indexOf(char).toString(2).padStart(5, "0");
	const key = Buffer.from(bits.match(/.{8}/g)!.map(byte => parseInt(byte, 2)));
	const counter = Buffer.alloc(8);
	counter.writeBigUInt64BE(BigInt(Math.floor(at / 30_000)));
	const hash = createHmac("sha1", key).update(counter).digest();
	const offset = hash[hash.length - 1]! & 0xf;
	return String((hash.readUInt32BE(offset) & 0x7fffffff) % 1_000_000).padStart(6, "0");
}

/** Waits for the next step of 30 s: the backend accepts a code only once */
export async function nextStep (page: Page): Promise<void> {
	await page.waitForTimeout(30_000 - (Date.now() % 30_000) + 500);
}

/**
 * Opens a page of the app (hash route) and turns on its semantics: Flutter draws on a canvas,
 * the semantics tree gives the DOM the texts, buttons and fields the tests use
 */
export async function open (page: Page, route: string): Promise<void> {
	await page.goto(`/#${route}`);
	await semantics(page);
}

export async function semantics (page: Page): Promise<void> {
	// Already on when only the route changed (no reload)
	const placeholder = page.locator("flt-semantics-placeholder");
	const tree = page.locator("flt-semantics").first();
	await expect(placeholder.or(tree)).toBeAttached({ timeout: 60_000 });
	if (await placeholder.count() > 0) await placeholder.evaluate(element => (element as HTMLElement).click());
	await expect(tree).toBeAttached();
}

/** Text field by its label: types like a user */
export async function fill (page: Page, label: string, value: string): Promise<void> {
	await type(page, page.getByLabel(label, { exact: true }), value);
}

/**
 * Click and keyboard: Flutter moves the focus to its own editing element, a value set on the
 * field of the semantics wouldn't reach the app
 */
export async function type (page: Page, field: Locator, value: string): Promise<void> {
	await field.click();
	// The first keys typed before the focus moves would be lost
	await page.waitForFunction(() => ["INPUT", "TEXTAREA"].includes(document.activeElement?.tagName ?? ""));
	await page.waitForTimeout(150);
	await page.keyboard.press("ControlOrMeta+A");
	await page.keyboard.press("Backspace");
	await page.keyboard.type(value);
}

/**
 * Click given to the element of the semantics: for the controls that an empty node of the
 * semantics covers (segmented buttons), where a click by coordinates wouldn't reach them
 */
export async function press (target: Locator): Promise<void> {
	await target.evaluate(element => (element as HTMLElement).click());
}

/**
 * Clicks by coordinates on the canvas (a map): the semantics would turn them into a tap of
 * the node without its position, so it lets the pointer through meanwhile
 */
export async function clickCanvas (page: Page, points: { x: number; y: number }[]): Promise<void> {
	await page.evaluate(() => {
		const style = document.createElement("style");
		style.id = "e2e-pointer";
		style.textContent = "flt-semantics-host, flt-semantics-host * { pointer-events: none !important; }";
		document.head.append(style);
	});
	for (const point of points) {
		await page.mouse.click(point.x, point.y);
		await page.waitForTimeout(300);
	}
	await page.evaluate(() => document.getElementById("e2e-pointer")?.remove());
}

export async function tap (page: Page, name: string): Promise<void> {
	await page.getByRole("button", { name, exact: true }).click();
}
